BEGIN;
CREATE TABLE app.ledger_book(id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES control_plane.tenant(id),code varchar(80) NOT NULL,currency char(3) NOT NULL CHECK(currency='GBP'),chart_status varchar(24) NOT NULL CHECK(chart_status IN('synthetic','reference_pending_d02')),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,code),UNIQUE(tenant_id,id,currency));
CREATE TABLE app.ledger_account(id uuid NOT NULL,tenant_id uuid NOT NULL,book_id uuid NOT NULL,currency char(3) NOT NULL,code varchar(80) NOT NULL,class varchar(32) NOT NULL CHECK(class IN('receivable','cash','provider_clearing','tax_payable','recognized_income','deferred_income')),mapping_status varchar(24) NOT NULL CHECK(mapping_status IN('synthetic','reference_pending_d02')),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,book_id,code),UNIQUE(tenant_id,book_id,id,currency),FOREIGN KEY(tenant_id,book_id,currency) REFERENCES app.ledger_book(tenant_id,id,currency));
CREATE TABLE app.financial_authorization(id uuid NOT NULL,tenant_id uuid NOT NULL,membership_id uuid NOT NULL,purpose varchar(32) NOT NULL CHECK(purpose IN('plan_obligation','plan_settlement','correction')),amount_pence bigint NOT NULL CHECK(amount_pence>0),currency char(3) NOT NULL CHECK(currency='GBP'),artifact_hash char(64) NOT NULL CHECK(artifact_hash~'^[0-9a-f]{64}$'),status varchar(12) NOT NULL CHECK(status IN('approved','revoked','expired')),expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,membership_id) REFERENCES app.membership(tenant_id,id));
CREATE TABLE app.journal(id uuid NOT NULL,tenant_id uuid NOT NULL,book_id uuid NOT NULL,currency char(3) NOT NULL,kind varchar(24) NOT NULL CHECK(kind IN('plan_obligation','plan_settlement','reversal')),source_event_id varchar(200) NOT NULL,provenance_kind varchar(40) NOT NULL,provenance_ref varchar(200) NOT NULL,artifact_hash char(64) NOT NULL CHECK(artifact_hash~'^[0-9a-f]{64}$'),authorization_id uuid NOT NULL,audit_event_id uuid NOT NULL,obligation_journal_id uuid,reverses_journal_id uuid,posted_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,source_event_id),UNIQUE(tenant_id,authorization_id),UNIQUE(tenant_id,book_id,id,currency),FOREIGN KEY(tenant_id,book_id,currency) REFERENCES app.ledger_book(tenant_id,id,currency),FOREIGN KEY(tenant_id,authorization_id) REFERENCES app.financial_authorization(tenant_id,id),FOREIGN KEY(tenant_id,audit_event_id) REFERENCES app.audit_event(tenant_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(tenant_id,book_id,obligation_journal_id,currency) REFERENCES app.journal(tenant_id,book_id,id,currency),FOREIGN KEY(tenant_id,book_id,reverses_journal_id,currency) REFERENCES app.journal(tenant_id,book_id,id,currency),CHECK((kind='plan_obligation' AND obligation_journal_id IS NULL AND reverses_journal_id IS NULL)OR(kind='plan_settlement' AND obligation_journal_id IS NOT NULL AND reverses_journal_id IS NULL)OR(kind='reversal' AND obligation_journal_id IS NULL AND reverses_journal_id IS NOT NULL)));
CREATE TABLE app.journal_line(id uuid NOT NULL,tenant_id uuid NOT NULL,book_id uuid NOT NULL,journal_id uuid NOT NULL,account_id uuid NOT NULL,currency char(3) NOT NULL,side varchar(6) NOT NULL CHECK(side IN('debit','credit')),amount_pence bigint NOT NULL CHECK(amount_pence>0),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,book_id,journal_id,currency) REFERENCES app.journal(tenant_id,book_id,id,currency),FOREIGN KEY(tenant_id,book_id,account_id,currency) REFERENCES app.ledger_account(tenant_id,book_id,id,currency));
CREATE VIEW app.ledger_balance WITH(security_barrier=true) AS SELECT tenant_id,book_id,account_id,currency,sum(CASE WHEN side='debit' THEN amount_pence ELSE -amount_pence END)::bigint balance_pence FROM app.journal_line GROUP BY tenant_id,book_id,account_id,currency;
CREATE FUNCTION app.reject_ledger_mutation()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'posted financial records are immutable' USING ERRCODE='55000';END $$ ;
CREATE TRIGGER journal_immutable BEFORE UPDATE OR DELETE ON app.journal FOR EACH ROW EXECUTE FUNCTION app.reject_ledger_mutation();CREATE TRIGGER journal_line_immutable BEFORE UPDATE OR DELETE ON app.journal_line FOR EACH ROW EXECUTE FUNCTION app.reject_ledger_mutation();
-- Cross-row balance is deliberately a deferred constraint trigger, never a CHECK.
CREATE FUNCTION app.assert_journal_balanced()RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE t uuid;j uuid;n bigint;d numeric;c numeric;ok boolean;BEGIN IF TG_TABLE_NAME='journal' THEN t:=COALESCE(NEW.tenant_id,OLD.tenant_id);j:=COALESCE(NEW.id,OLD.id);ELSE t:=COALESCE(NEW.tenant_id,OLD.tenant_id);j:=COALESCE(NEW.journal_id,OLD.journal_id);END IF;SELECT count(*),COALESCE(sum(amount_pence)FILTER(WHERE side='debit'),0),COALESCE(sum(amount_pence)FILTER(WHERE side='credit'),0)INTO n,d,c FROM app.journal_line WHERE tenant_id=t AND journal_id=j;IF n=0 OR d<>c THEN RAISE EXCEPTION 'journal must contain balanced non-zero lines' USING ERRCODE='23514';END IF;SELECT EXISTS(SELECT 1 FROM app.journal x JOIN app.audit_event a ON(a.tenant_id,a.id)=(x.tenant_id,x.audit_event_id)WHERE x.tenant_id=t AND x.id=j AND a.event_type='financial.journal_posted' AND a.subject_type='journal' AND a.subject_ref=x.id::text)INTO ok;IF NOT ok THEN RAISE EXCEPTION 'journal requires matching audit event' USING ERRCODE='23514';END IF;RETURN NULL;END $$ ;
CREATE CONSTRAINT TRIGGER journal_balanced AFTER INSERT OR UPDATE ON app.journal DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.assert_journal_balanced();CREATE CONSTRAINT TRIGGER journal_line_balanced AFTER INSERT OR UPDATE OR DELETE ON app.journal_line DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.assert_journal_balanced();
CREATE FUNCTION app.assert_financial_authorization(t uuid,a uuid,p varchar,n bigint,c char,h char)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$ DECLARE x app.financial_authorization;BEGIN SELECT*INTO x FROM app.financial_authorization WHERE tenant_id=t AND id=a FOR UPDATE;IF NOT FOUND OR x.status<>'approved' OR x.purpose<>p OR x.amount_pence<>n OR x.currency<>c OR x.artifact_hash<>h OR(x.expires_at IS NOT NULL AND x.expires_at<=clock_timestamp())THEN RAISE EXCEPTION 'exact approved financial authorization required' USING ERRCODE='42501';END IF;END $$ ;
CREATE FUNCTION app.post_plan_obligation(j uuid,b uuid,r uuid,i uuid,n bigint,c char(3),s varchar,pk varchar,pr varchar,h char(64),a uuid,au uuid)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;BEGIN IF t IS NULL OR pk<>'synthetic_authorized_plan' THEN RAISE EXCEPTION 'unsupported obligation provenance' USING ERRCODE='42501';END IF;PERFORM app.assert_financial_authorization(t,a,'plan_obligation',n,c,h);INSERT INTO app.journal(id,tenant_id,book_id,currency,kind,source_event_id,provenance_kind,provenance_ref,artifact_hash,authorization_id,audit_event_id)VALUES(j,t,b,c,'plan_obligation',s,pk,pr,h,a,au);INSERT INTO app.journal_line(id,tenant_id,book_id,journal_id,account_id,currency,side,amount_pence)VALUES(gen_random_uuid(),t,b,j,r,c,'debit',n),(gen_random_uuid(),t,b,j,i,c,'credit',n);RETURN j;END $$ ;
CREATE FUNCTION app.post_plan_settlement(j uuid,b uuid,o uuid,cl uuid,r uuid,n bigint,c char(3),s varchar,pr varchar,h char(64),a uuid,au uuid)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;outstanding bigint;BEGIN PERFORM 1 FROM app.journal WHERE tenant_id=t AND id=o AND kind='plan_obligation' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'obligation not found' USING ERRCODE='P0002';END IF;SELECT ol.amount_pence-COALESCE(sum(sl.amount_pence),0)INTO outstanding FROM app.journal_line ol LEFT JOIN app.journal x ON x.tenant_id=ol.tenant_id AND x.obligation_journal_id=ol.journal_id AND x.kind='plan_settlement' LEFT JOIN app.journal_line sl ON sl.tenant_id=x.tenant_id AND sl.journal_id=x.id AND sl.account_id=ol.account_id AND sl.side='credit' WHERE ol.tenant_id=t AND ol.journal_id=o AND ol.account_id=r AND ol.side='debit' GROUP BY ol.amount_pence;IF outstanding IS NULL OR n>outstanding THEN RAISE EXCEPTION 'settlement exceeds outstanding receivable' USING ERRCODE='23514';END IF;PERFORM app.assert_financial_authorization(t,a,'plan_settlement',n,c,h);INSERT INTO app.journal(id,tenant_id,book_id,currency,kind,source_event_id,provenance_kind,provenance_ref,artifact_hash,authorization_id,audit_event_id,obligation_journal_id)VALUES(j,t,b,c,'plan_settlement',s,'authorized_settlement',pr,h,a,au,o);INSERT INTO app.journal_line(id,tenant_id,book_id,journal_id,account_id,currency,side,amount_pence)VALUES(gen_random_uuid(),t,b,j,cl,c,'debit',n),(gen_random_uuid(),t,b,j,r,c,'credit',n);RETURN j;END $$ ;
CREATE FUNCTION app.reverse_journal(j uuid,b uuid,o uuid,s varchar,pr varchar,h char(64),a uuid,au uuid)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;n bigint;c char(3);BEGIN SELECT sum(amount_pence)FILTER(WHERE side='debit'),currency INTO n,c FROM app.journal_line WHERE tenant_id=t AND book_id=b AND journal_id=o GROUP BY currency;IF n IS NULL THEN RAISE EXCEPTION 'original journal not found' USING ERRCODE='P0002';END IF;PERFORM app.assert_financial_authorization(t,a,'correction',n,c,h);INSERT INTO app.journal(id,tenant_id,book_id,currency,kind,source_event_id,provenance_kind,provenance_ref,artifact_hash,authorization_id,audit_event_id,reverses_journal_id)VALUES(j,t,b,c,'reversal',s,'authorized_correction',pr,h,a,au,o);INSERT INTO app.journal_line(id,tenant_id,book_id,journal_id,account_id,currency,side,amount_pence)SELECT gen_random_uuid(),tenant_id,book_id,j,account_id,currency,CASE side WHEN'debit'THEN'credit'ELSE'debit'END,amount_pence FROM app.journal_line WHERE tenant_id=t AND journal_id=o;RETURN j;END $$ ;
CREATE FUNCTION app.post_recovery_fee_candidate(jsonb)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$ BEGIN RAISE EXCEPTION 'recovery fee posting disabled: qualifying landing and approvals absent' USING ERRCODE='0A000';END $$ ;
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['ledger_book','ledger_account','financial_authorization','journal','journal_line']LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',n);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',n);EXECUTE format('GRANT SELECT ON app.%I TO jobguard_runtime',n);EXECUTE format('REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',n);END LOOP;END $$ ;
GRANT SELECT ON app.ledger_balance TO jobguard_runtime;ALTER VIEW app.ledger_balance OWNER TO jobguard_migration;
ALTER FUNCTION app.reject_ledger_mutation()OWNER TO jobguard_migration;ALTER FUNCTION app.assert_journal_balanced()OWNER TO jobguard_migration;ALTER FUNCTION app.assert_financial_authorization(uuid,uuid,varchar,bigint,char,char)OWNER TO jobguard_migration;ALTER FUNCTION app.post_plan_obligation(uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,varchar,char,uuid,uuid)OWNER TO jobguard_migration;ALTER FUNCTION app.post_plan_settlement(uuid,uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,char,uuid,uuid)OWNER TO jobguard_migration;ALTER FUNCTION app.reverse_journal(uuid,uuid,uuid,varchar,varchar,char,uuid,uuid)OWNER TO jobguard_migration;ALTER FUNCTION app.post_recovery_fee_candidate(jsonb)OWNER TO jobguard_migration;
REVOKE ALL ON FUNCTION app.assert_financial_authorization(uuid,uuid,varchar,bigint,char,char),app.post_plan_obligation(uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,varchar,char,uuid,uuid),app.post_plan_settlement(uuid,uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,char,uuid,uuid),app.reverse_journal(uuid,uuid,uuid,varchar,varchar,char,uuid,uuid),app.post_recovery_fee_candidate(jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.post_plan_obligation(uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,varchar,char,uuid,uuid),app.post_plan_settlement(uuid,uuid,uuid,uuid,uuid,bigint,char,varchar,varchar,char,uuid,uuid),app.reverse_journal(uuid,uuid,uuid,varchar,varchar,char,uuid,uuid),app.post_recovery_fee_candidate(jsonb)TO jobguard_runtime;
COMMIT;
